"use client";

import { createContext, useContext, useState, useCallback, ReactNode } from "react";
import ConfirmDialog, { type RequireConfirmationInput } from "./confirm-dialog";

export type { RequireConfirmationInput };

interface ConfirmOptions {
	title?: string;
	description?: string;
	confirmButtonText?: string;
	cancelButtonText?: string;
	variant?: "default" | "destructive";
	requireConfirmationInput?: RequireConfirmationInput;
}

interface ConfirmContextType {
	confirm: (options: ConfirmOptions) => Promise<boolean>;
}

const ConfirmContext = createContext<ConfirmContextType | undefined>(undefined);

export const ConfirmDialogProvider = ({ children }: { children: ReactNode }) => {
	const [options, setOptions] = useState<ConfirmOptions>({});
	const [isOpen, setIsOpen] = useState(false);
	const [resolver, setResolver] = useState<((value: boolean) => void) | null>(null);

	const confirm = useCallback((confirmOptions: ConfirmOptions) => {
		setResolver((prev: ((value: boolean) => void) | null) => {
			if (prev) {
				prev(false);
			}
			return null;
		});

		setOptions(confirmOptions);
		setIsOpen(true);
		return new Promise<boolean>((resolve) => {
			setResolver(() => resolve);
		});
	}, []);

	const handleConfirm = () => {
		if (resolver) {
			resolver(true);
		}
		setIsOpen(false);
		setResolver(null);
	};

	const handleCancel = () => {
		if (resolver) {
			resolver(false);
		}
		setIsOpen(false);
		setResolver(null);
	};

	return (
		<ConfirmContext.Provider value={{ confirm }}>
			{children}
			<ConfirmDialog
				isOpen={isOpen}
				title={options.title || "Confirm Action"}
				description={options.description || "Are you sure you want to proceed?"}
				confirmButtonText={options.confirmButtonText || "Confirm"}
				cancelButtonText={options.cancelButtonText || "Cancel"}
				variant={options.variant || "default"}
				requireConfirmationInput={options.requireConfirmationInput}
				onConfirm={handleConfirm}
				onCancel={handleCancel}
			/>
		</ConfirmContext.Provider>
	);
};

export const useConfirm = () => {
	const context = useContext(ConfirmContext);
	if (!context) {
		throw new Error("useConfirm must be used within a ConfirmDialogProvider");
	}
	return context.confirm;
};

"use client";

import { useState } from "react";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog"
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface RequireConfirmationInput {
	confirmTerm: string;
	/** Custom label with {{confirmTerm}} placeholder for the required term (bold). Default: "Type {{confirmTerm}} to confirm" */
	label?: string;
	hint?: string;
}

interface ConfirmDialogProps {
	title: string;
	description: string;
	confirmButtonText: string;
	cancelButtonText: string;
	onConfirm: () => void;
	onCancel: () => void;
	variant: "default" | "destructive";
	isOpen: boolean;
	requireConfirmationInput?: RequireConfirmationInput;
}

const ConfirmDialog = (props: ConfirmDialogProps) => {
	const [typedValue, setTypedValue] = useState("");

	const requireTyped = props.requireConfirmationInput;
	const requiredTerm = requireTyped?.confirmTerm ?? "";
	const canConfirm = !requireTyped || typedValue === requiredTerm;

	const labelMessage = requireTyped?.label ?? "Type {{confirmTerm}} to confirm";
	const labelParts = labelMessage.split("{{confirmTerm}}");

	return (
		<AlertDialog
			open={props.isOpen}
			onOpenChange={(open) => {
				if (!open) {
					setTypedValue("");
					props.onCancel();
				}
			}}
		>
			<AlertDialogContent>
				<AlertDialogHeader>
					<AlertDialogTitle>{props.title}</AlertDialogTitle>
					<AlertDialogDescription>{props.description}</AlertDialogDescription>
				</AlertDialogHeader>
				{requireTyped && (
					<div className="grid gap-2">
						<Label htmlFor="confirm-type-input">
							{labelParts.map((part, i) =>
								i < labelParts.length - 1 ? (
									<span key={i}>{part}<span className="font-bold">{requiredTerm}</span></span>
								) : (
									<span key={i}>{part}</span>
								)
							)}
						</Label>
						<Input
							id="confirm-type-input"
							value={typedValue}
							onChange={(e) => setTypedValue(e.target.value)}
							onKeyDown={(e) => {
								if (e.key === "Enter" && canConfirm) {
									e.preventDefault();
									setTypedValue("");
									props.onConfirm();
								}
							}}
							placeholder={requiredTerm}
							autoComplete="off"
						/>
						{requireTyped.hint && (
							<p className="text-muted-foreground text-xs">{requireTyped.hint}</p>
						)}
					</div>
				)}
				<AlertDialogFooter>
					<AlertDialogCancel
						onClick={(e) => {
							e.preventDefault();
							setTypedValue("");
							props.onCancel();
						}}
					>
						{props.cancelButtonText}
					</AlertDialogCancel>
					<AlertDialogAction
						variant={props.variant}
						disabled={!canConfirm}
						onClick={(e) => {
							e.preventDefault();
							setTypedValue("");
							props.onConfirm();
						}}
					>
						{props.confirmButtonText}
					</AlertDialogAction>
				</AlertDialogFooter>
			</AlertDialogContent>
		</AlertDialog>
	);
};

export default ConfirmDialog;
